contract InvMutTest {
    C public c;
    bool public callResult;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, string calldata description) external {
        // Grant admin role to caller
        c.isAdmin(caller);
        // Make caller a non-admin (isAdmin defaults to false)
        // Now try to call newEmergencyOracle as the caller
        (bool success, ) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));
        require(msg.sender == caller, "caller must be the test initiator");
        assert(!success);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, string calldata desc) public payable {
        require(true);
        bool reverted;
        vm.prank(caller);
        try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        bool isAdmin = c.isAdmin(caller);
        assert(reverted == !isAdmin);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, string calldata desc) public payable {
        require(true);
        c.isAdmin(caller);
        bool reverted; try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        assert(reverted != c.isAdmin(caller));
    }
    receive() external payable {}
