contract InvMutTest {
    C public c;
    bool revertFlag;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, string calldata desc) external {
        c.isAdmin(caller);
        revertFlag = false;
        (bool success, ) = address(c).call(abi.encodeWithSelector(C.newEmergencyOracle.selector, desc));
        if (!success) {
            revertFlag = true;
        }
        assert(c.isAdmin(caller) || !revertFlag);
    }
