contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, string calldata desc) public payable {
        require(!c.isAdmin(caller));
        bool reverted;
        try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
}

