pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(string calldata description) public {
        // Make the caller an admin
        vm.prank(address(this));
        c.isAdmin(address(this)) = true;
        // Call the entry point
        vm.prank(address(this));
        c.newEmergencyOracle(description);
        // Get the deployed oracle address from the emitted event
        vm.recordLogs();
        vm.prank(address(this));
        c.newEmergencyOracle(description);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        // The first topic-less event is NewEmergencyOracle; its second indexed param is the oracle address
        address newOracle = address(uint160(uint256(entries[0].topics[2])));
        // The rule: the oracle owner is the caller of newEmergencyOracle (address(this)), never address(0)
        assertTrue(newOracle != address(0));
    }
}

