pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(string calldata description) public {
        // Make the caller an admin so the onlyAdmin modifier passes
        c.isAdmin(address(this));
        assertTrue(c.isAdmin(address(this)), "setUp admin failed");
        // Call newEmergencyOracle with the fuzzed description
        c.newEmergencyOracle(description);
        // The newEmergencyOracle function does not return the deployed address,
        // but we can derive it from the emitted event.
        // We read the event to obtain the deployed oracle address.
        vm.recordLogs();
        c.newEmergencyOracle(description);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // Expect at least one log with topic NewEmergencyOracle(address,address)
        require(logs.length > 0, "no logs");
        // Parse the third topic (indexed parameter newOracle) as address
        address deployedOracle = address(uint160(uint256(logs[0].topics[2])));
        // Read the owner of the deployed EmergencyOracle
        EmergencyOracle oracle = EmergencyOracle(deployedOracle);
        address oracleOwner = oracle.owner();
        // General rule: the owner of the deployed oracle must be msg.sender (i.e. address(this))
        assertTrue(oracleOwner == address(this), "oracle owner is not caller");
    }
}

